42: function render(){const worth=netWorth();$('#dayTop').textContent=state.day;$('#actionDay').textContent=state.day;$('#seasonTop').textContent=['EARLY SPRING','HIGH SUMMER','LATE AUTUMN','DEEP WINTER'][Math.floor((state.day-1)/18)%4];$('#sideName').textContent=state.name;$('#sideRank').textContent=rank().toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());$('#rankBadge').textContent='●  '+rank();$('#stats').innerHTML=statCard('CASH ON HAND',money(state.cash),'Your next move starts here','💵')+statCard('NET WORTH',money(worth),`${state.owned.length} assets owned`,'◈')+statCard('YOUR RESPECT',state.rep+' / 100',rank(),'✦')+statCard('CITY ATTENTION',state.heat+' / 100',state.heat>65?'Things feel tense':'Keep your profile in mind','◉',state.heat>65?'negative':'');$('#heatText').textContent=state.heat+' / 100';$('#heatBar').style.width=state.heat+'%';$('#heatBar').style.background=state.heat>65?'var(--red)':'var(--orange)';$('#respectText').textContent=state.rep+' / 100';$('#respectBar').style.width=state.rep+'%';$('#repCaption').textContent=state.rep>=70?'A name across the city':state.rep>=35?'People know your face':state.rep>=10?'Word is starting to spread':'Just getting started';$('#weatherTag').textContent=state.heat>65?'⚠  THE CITY IS WATCHING':state.heat>35?'✦  TENSION IS RISING':'✦  TENSION IS LOW';$('#greeting').textContent=state.day===1?'You came up with nothing. The whole city is in play.':`${rank().toLowerCase()} and counting. Every day is another chance to make a name.`;$('#homeEvents').innerHTML=eventMarkup(state.events.slice(0,4));$('#ledgerEvents').innerHTML=eventMarkup(state.events);$('#ledgerCaption').textContent=`${state.day} days into your story · ${state.events.length} moments remembered`;renderInventory();renderMarket();renderSuppliers();renderContacts();renderAssets();$('[data-view="'+state.activeView+'"]')?.classList.add('active');save()}
43: function eventMarkup(events){return events.length?events.map(e=>`<div class="event"><i class="event-dot" style="background:${e.type==='bad'?'var(--orange)':e.type==='good'?'var(--green)':'var(--lime)'}"></i><div class="event-copy">${e.text}<small>DAY ${e.day}</small></div></div>`).join(''):'<div class="empty">Your story is just beginning.<br>Make a move and it will show up here.</div>'}
44: function renderInventory(){const list=$('#inventoryList');const entries=GOODS.filter(g=>(state.inventory[g.id]||0)>0);$('#inventoryCount').textContent=entries.reduce((n,g)=>n+state.inventory[g.id],0)+' items';list.innerHTML=entries.length?entries.map(g=>`<div class="row"><div class="row-icon">${g.icon}</div><div class="row-body"><div class="row-name">${g.name}</div><div class="row-desc">${g.desc}</div></div><div class="row-side"><div class="row-price">${state.inventory[g.id]} units</div><div class="row-sub">Market ${money(priceOf(g))} ea.</div><button class="btn small" style="margin-top:7px" data-sell="${g.id}">Find buyer</button></div></div>`).join(''):'<div class="empty">Your pockets are empty.<br>Check the market to find a supplier.</div>'}
45: function renderMarket(){const list=$('#marketList');list.innerHTML=GOODS.map(g=>{const p=priceOf(g);return `<div class="row"><div class="row-icon">${g.icon}</div><div class="row-body"><div class="row-name">${g.name}</div><div class="row-desc">${g.desc}</div><div class="row-sub">Market price ${money(p)} / unit</div></div><div class="row-side"><div class="row-price">${money(p)}<small style="font-size:9px;color:#85868e"> /ea</small></div><button class="btn small" style="margin-top:7px" data-buy="${g.id}">Buy stock</button></div></div>`}).join('');const buyers=$('#customersList');buyers.innerHTML=state.customers.length?state.customers.map(c=>{const g=GOODS.find(x=>x.id===c.good);return `<div class="row"><div class="row-icon">${c.icon}</div><div class="row-body"><div class="row-name">${c.name} <span class="chip blue">WANTS ${g.name.toUpperCase()}</span></div><div class="row-desc">${c.note}</div></div><div class="row-side"><div class="row-price">${money(c.offer)}<small style="font-size:9px;color:#85868e"> /ea</small></div><button class="btn small" style="margin-top:7px" data-customer="${c.id}">Talk deal</button></div></div>`}).join(''):'<div class="empty">No one is looking right now.<br>Work the neighborhood to meet buyers.</div>'}
46: function renderSuppliers(){$('#suppliersList').innerHTML=SUPPLIERS.map(s=>{const trust=state.suppliers[s.id]||0;return `<div class="row"><div class="row-icon">${s.icon}</div><div class="row-body"><div class="row-name">${s.name} <span class="chip ${trust>=3?'green':''}">${trust<2?'NEW CONTACT':trust<5?'WARMING UP':'TRUSTED'}</span></div><div class="row-desc">${s.style}</div><div class="barline"><i style="width:${trust*10}%;background:var(--blue)"></i></div></div><div class="row-side"><div class="row-sub">TRUST ${trust}/10</div><button class="btn secondary small" style="margin-top:7px" data-negotiate="${s.id}">Negotiate</button></div></div>`}).join('')}
47: function renderContacts(){const contacts=state.contacts;$('#contactsList').innerHTML=contacts.length?contacts.map(c=>`<div class="row"><div class="row-icon">${c.icon}</div><div class="row-body"><div class="row-name">${c.name}</div><div class="row-desc">${c.note}</div></div><span class="chip ${c.status==='active'?'green':''}">${c.status==='active'?'ACTIVE':'KNOWN'}</span></div>`).join(''):'<div class="empty">No contacts yet.<br>Work the neighborhood to meet people.</div>'}
48: function renderAssets(){const houses=$('#housesList'),gear=$('#gearList');houses.innerHTML=HOUSES.map(a=>assetRow(a)).join('');gear.innerHTML=GEAR.map(a=>assetRow(a)).join('');$('#cityChoices').innerHTML=`<div class="row"><div class="row-icon">🕊️</div><div class="row-body"><div class="row-name">Smooth things over</div><div class="row-desc">A fictional favor to reduce city attention. Costs more as your name grows.</div></div><div class="row-side"><div class="row-price">${money(250+state.rep*65)}</div><button class="btn secondary small" style="margin-top:7px" data-action="influence">Make a call</button></div></div><div class="row"><div class="row-icon">🌙</div><div class="row-body"><div class="row-name">Take a quiet day</div><div class="row-desc">Step back from the noise and let things cool naturally.</div></div><div class="row-side"><div class="row-price">Free</div><button class="btn secondary small" style="margin-top:7px" data-action="laylow">Lay low</button></div></div>`}
